,reason)=('legacy-account','24242424-2424-4242-8242-242424242424','reconciliation_required','legacy_unverifiable'))||':'||(SELECT count(*)FROM salesflow.intent_transitions WHERE(account_ref,intent_id,to_state,reason)=('legacy-account','24242424-2424-4242-8242-242424242424','reconciliation_required','legacy_unverifiable'))||':'||(SELECT count(*)FROM salesflow.provider_call_events WHERE(account_ref,intent_id,event_key,reason)=('legacy-account','24242424-2424-4242-8242-242424242424','migration-request-hash-upgrade','legacy_unverifiable'))||':'||(SELECT count(*)FROM salesflow.followups WHERE(account_ref,id,state,reason)=('legacy-account','26262626-2626-4262-8262-262626262626','reconciliation_required','legacy_unverifiable'))FROM salesflow.contacts WHERE account_ref='legacy-account'";Native 'legacy upgrade evidence query';$legacyTuple=$legacyResult.Trim();Assert ($legacyTuple-eq'4:1:0:1:1:0:4:5:1:1:1:1:1:1') "legacy UUID, history, processing-body backfill, duplicate, terminal-identity, and post-call Follow-Up reconciliation, deterministic index replacement, exact sentinel, and identifier backfill preserved: $legacyTuple"
