  foreach($f in Get-ChildItem config -Filter *.json|? Name -ne account.json){$j=Get-Content $f.FullName -Raw;$q=$j-replace"'","''";$b=$j|ConvertFrom-Json;$r=ConfigJson "SELECT salesflow.save_config('$op','$q');" "save $($f.Name) a";Assert $r.created "$($f.Name) a created";$expected=if($b.kind-eq'release_set'){"'release-v8'"}elseif($b.kind-eq'consent_templates'){"'consent-v1'"}else{'NULL'};$r=ConfigJson "SELECT salesflow.activate_config('$op','$($b.accountRef)','$($b.kind)','$($b.version)',$expected);" "activate $($f.Name) a";Assert $r.activated "$($f.Name) a activated";$b.accountRef='account-b';$q=(($b|ConvertTo-Json -Compress -Depth 20)-replace"'","''");$r=ConfigJson "SELECT salesflow.save_config('$op2','$q');" "save $($f.Name) b";Assert $r.created "$($f.Name) b created";$r=ConfigJson "SELECT salesflow.activate_config('$op2','account-b','$($b.kind)','$($b.version)',NULL);" "activate $($f.Name) b";Assert $r.activated "$($f.Name) b activated"}
