  $freshTurnSeed=ConfigJson "SELECT salesflow.ingest('$rt',jsonb_build_object('account_ref','test-account','provider_id','sp3t3-fresh-complete-turn','contact_ref','sp3t3-fresh-complete-turn','body','hello'));" 'fresh-transaction complete-turn seed';$null=ConfigJson "SELECT salesflow.set_consent('$rt','test-account','$($freshTurnSeed.contact_id)'::uuid,'granted','fresh-transaction complete-turn');" 'fresh-transaction complete-turn consent';$freshTurn=ConfigJson "SELECT salesflow.complete_turn('$rt','test-account','$($freshTurnSeed.conversation_id)'::uuid);" 'fresh-transaction complete-turn';Assert ($freshTurn.terminal-eq'created') 'complete_turn establishes its lock deadline in a fresh database transaction'
