  @"
SET search_path=salesflow,public;
DO `$sp3t3_concurrency_fixture`$
DECLARE rt text:='sp3t3-concurrency-token';acct text:='sp3t3-concurrency';label text;r jsonb;r2 jsonb;c uuid;v uuid;source_work uuid;source_lease uuid;corr uuid;pid text;child uuid;f followups;
BEGIN
